<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Fees Paid Receipt</h1><p>Persisted payment receipt</p></div><?php if($receipt):?><button class="btn btn--primary" onclick="window.print()">Print Receipt</button><?php endif ?></header><?php if(!$receipt):?><section class="module-card"><div class="compact-empty"><h3>Select a payment from Collect Fees to view its receipt.</h3></div></section><?php else:?><section class="module-card"><header class="module-card__header"><div><h2><?= e($receipt['institute_name']) ?></h2><p><?= e($receipt['institute_address']) ?></p></div><strong><?= e($receipt['receipt_no']) ?></strong></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three"><?php foreach(['Student'=>'student_name','Registration'=>'registration_no','Class'=>'class_name','Fee Month'=>'fee_month','Payment Date'=>'payment_date','Method'=>'payment_method','Received By'=>'received_by_name']as$l=>$k):?><div class="module-field"><label><?= $l ?></label><strong><?= e($receipt[$k]) ?></strong></div><?php endforeach ?></div><table class="data-table"><thead><tr><th>Particular</th><th>Amount</th></tr></thead><tbody><?php foreach($items as$item):?><tr><td><?= e($item['particular']) ?></td><td><?= number_format((float)$item['amount'],2) ?></td></tr><?php endforeach ?></tbody></table><div class="metric-grid"><div class="metric-card"><span>Previous Balance</span><strong><?= number_format((float)$receipt['previous_balance'],2) ?></strong></div><div class="metric-card"><span>Discount</span><strong><?= number_format((float)$receipt['discount'],2) ?></strong></div><div class="metric-card"><span>Total Due</span><strong><?= number_format((float)$receipt['total_amount'],2) ?></strong></div><div class="metric-card"><span>Paid This Receipt</span><strong><?= number_format((float)$receipt['payment_amount'],2) ?></strong></div><div class="metric-card"><span>Remaining</span><strong><?= number_format((float)$receipt['remaining_amount'],2) ?></strong></div></div></div></section><?php endif ?></div></div></main>
